}elseif($p==='assessment'){
 $assetId=(int)($_GET['asset']??0);$assets=$pdo->query('SELECT * FROM assets WHERE active=1 ORDER BY type,name')->fetchAll();if(!$assetId&&$assets)$assetId=$assets[0]['id'];$asset=null;foreach($assets as $a)if($a['id']==$assetId)$asset=$a;if(!$asset){page_header('Assessment');echo '<section class="card empty">No asset found.</section>';page_footer();exit;}$cs=$pdo->prepare('SELECT c.*,d.name domain,(SELECT status FROM assessments x WHERE x.asset_id=? AND x.control_id=c.id) status,(SELECT notes FROM assessments x WHERE x.asset_id=? AND x.control_id=c.id) notes FROM controls c JOIN domains d ON d.id=c.domain_id WHERE d.name=? AND c.active=1 ORDER BY c.id');$cs->execute([$assetId,$assetId,$asset['type']]);$controls=$cs->fetchAll();if($_SERVER['REQUEST_METHOD']==='POST'){foreach($controls as $c){$status=$_POST['status'][$c['id']]??'N/A';$note=$_POST['notes'][$c['id']]??'';$q=$pdo->prepare('INSERT INTO assessments(asset_id,control_id,status,notes) VALUES(?,?,?,?) ON CONFLICT(asset_id,control_id) DO UPDATE SET status=excluded.status,notes=excluded.notes,assessed_at=CURRENT_TIMESTAMP');$q->execute([$assetId,$c['id'],$status,$note]);}header('Location:?p=assessment&asset='.$assetId.'&saved=1');exit;}$yes=$no=$na=0;foreach($controls as $c){${strtolower($c['status']??'na')}++;}$den=$yes+$no;$score=$den?round($yes/$den*100):0;page_header('Assessment');?><section class="toolbar"><div><span class="pill"><?=$asset['type']?></span><h2><?=$asset['name']?></h2><p class="mono"><?=$asset['asset_code']?> · <?=$asset['ip_address']?> · <?=$asset['location']?></p></div><div class="mini-score"><b><?=$score?>%</b><small><?=$yes?> YES / <?=$no?> NO / <?=$na?> N/A</small></div></section><form method="post"><section class="card checklist"><div class="card-head"><div><small>SECURITY CONTROLS</small><h3>Checklist</h3></div></div><?php foreach($controls as $c):?><div class="check-row"><div><b><?=$c['name']?></b><small><?=$c['description']?></small></div><select name="status[<?=$c['id']?>]" class="status-<?=$c['status']??'N/A'?>"><option <?=$c['status']==='YES'?'selected':''?>>YES</option><option <?=$c['status']==='NO'?'selected':''?>>NO</option><option <?=$c['status']==='N/A'?'selected':''?>>N/A</option></select><input name="notes[<?=$c['id']?>]" value="<?=htmlspecialchars($c['notes']??'')?>" placeholder="Optional note / evidence"></div><?php endforeach;?></section><div class="form-actions"><button class="btn primary">Save assessment</button></div></form><?php page_footer();
