}elseif($p==='controls'){
 $rows=$pdo->query('SELECT c.*,d.name domain FROM controls c JOIN domains d ON d.id=c.domain_id ORDER BY d.id,c.id')->fetchAll();page_header('Security Controls');?><section class="toolbar"><div><span class="pill">CONFIGURABLE</span><h2>Security controls</h2><p>This is the key to flexible assessment: add a control once, then it appears automatically for matching assets.</p></div></section><section class="card table-wrap"><table><thead><tr><th>Domain</th><th>Control</th><th>Weight</th><th>Active</th></tr></thead><tbody><?php foreach($rows as $x):?><tr><td><span class="tag <?=$x['domain']?>"><?=$x['domain']?></span></td><td><b><?=$x['name']?></b></td><td><?=$x['weight']?></td><td><?=$x['active']?'YES':'NO'?></td></tr><?php endforeach;?></tbody></table></section><?php page_footer();
